func TestAuthoredEffectiveParamsMatchesActualPythonAlgorithm(t *testing.T) {
	var vectors []struct {
		Resolved  string `json:"resolved_jcs"`
		Effective string `json:"effective_jcs"`
	}
	if err := json.Unmarshal([]byte(authoredEffectivePythonVectors), &vectors); err != nil {
		t.Fatal(err)
	}
	if len(vectors) != 6 {
		t.Fatal("missing actual Python vectors")
	}
	for i, v := range vectors {
		before := []byte(v.Resolved)
		got, err := CompileAuthoredEffectiveParams(before)
		if err != nil || !bytes.Equal(got, []byte(v.Effective)) {
			t.Fatalf("Python effective vector %d mismatch: %v\n%s\n%s", i, err, got, v.Effective)
		}
		if string(before) != v.Resolved {
			t.Fatal("source mutated")
		}
	}
}
func TestAuthoredEffectiveParamsRejectsUnboundOrNoncanonicalResolved(t *testing.T) {
	var vectors []struct {
		Resolved string `json:"resolved_jcs"`
	}
	if err := json.Unmarshal([]byte(authoredEffectivePythonVectors), &vectors); err != nil {
		t.Fatal(err)
	}
	for _, raw := range [][]byte{nil, []byte("{}"), append([]byte(vectors[0].Resolved), '\n'), bytes.Replace([]byte(vectors[1].Resolved), []byte(`"strength":0.37`), []byte(`"strength":0.38`), 1)} {
		if _, err := CompileAuthoredEffectiveParams(raw); err == nil {
			t.Fatalf("malformed/stale source accepted: %s", raw)
		}
	}
}
